mapper.insert:

	SELECT (SELECT NVL(MAX(CURRICULUM_CODE), 0) FROM CLASS_CURRICULUM)
		+ SEQ_CLASS_CURRICULUM_CODE.NEXTVAL
	FROM DUAL

INSERT INTO CLASS_CURRICULUM (
	CURRICULUM_CODE, CLASS_CODE, CURRICULUM_TYPE,
	CURRICULUM_TITLE, CURRICULUM_CONTENT, CURRICULUM_IMG
) VALUES (
	#{curriculumCode}, #{classCode}, #{stepNo},
	#{title}, #{content}, #{imagePath}
)
